#!/usr/bin/env python3
"""Own static data/schema review; no import or execution of guard/compiler."""
import ast,json,re,hashlib
from pathlib import Path
W=Path('/tmp/zfc-r3-raw-form-quotation'); sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest(); G=W/'check.py'; B=W/'boundary.json'
tree=ast.parse(G.read_text()); b=json.loads(B.read_text()); checks=[]; inputs={}
def check(ok,name):
 assert ok,name
 checks.append(name)
def pin(p,h):
 p=Path(p).resolve(); check(p.is_file() and sha(p)==h,str(p)); check(str(p) not in inputs or inputs[str(p)]==h,'consistent identity '+str(p));inputs[str(p)]=h
pats=r"^'([^\n]+)'[ \t]+(?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)"
es={}
for k,d in b['parents'].items():
 pin(d['path'],d['sha256']);e=json.loads(Path(d['path']).read_text());es[k]=e
 check(e['before']==e['after'] and e['all_input_provider_postchecks'] and e['status']=='PASS','historical '+k)
 pairs=[(q['snapshot'],q['source_sha256'],q['audit_snapshot'],q['audit_sha256'],q['probes'],q['callers'],e['commands'][2*i+1]) for i,q in enumerate(e['sources'])] if k=='refresh' else [(e['source']['snapshot'],e['source']['sha256'],e['audit']['snapshot'],e['audit']['sha256'],None,11,e['commands'][1])]
 for sp,sh,ap,ah,expected,n,cmd in pairs:
  pin(sp,sh);pin(ap,ah);names=re.findall(r'^#print axioms (\S+)$',Path(ap).read_text(),re.M);rr=re.findall(pats,cmd['output'],re.M)
  check([q[0] for q in rr]==names and (expected is None or expected==names),'actual parent probe spelling '+k)
  check(len(re.findall(r'^example\b',Path(ap).read_text(),re.M))==n,'typed parent census '+k)
 for field in ['path','sha256','version']:check(e['compiler'][field]==b['compiler'][field],'compiler '+k+field)
for q in b['reused_modules']:
 e=es['refresh' if q['module']=='ZFCinPA.Instances' else 'binary'];old=next(r for r in e['reused_modules'] if r['module']==q['module'])
